insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-anatomy-note-101','Pharmacy','Diploma in Pharmacy','note','free',501,'{"title":"Introduction to Human Anatomy and Physiology","english":"Anatomy is the study of body structures; physiology is the study of how those structures function. The structural levels are chemical, cellular, tissue, organ, organ system and organism. The four basic tissue types are epithelial, connective, muscle and nervous tissue. Homeostasis is the maintenance of a relatively stable internal environment through regulatory mechanisms, often involving negative feedback.","nepali":"Anatomy भनेको शरीरका संरचनाको अध्ययन हो र physiology भनेको ती संरचनाले कसरी काम गर्छन् भन्ने अध्ययन हो। शरीरको संरचनात्मक तह chemical, cellular, tissue, organ, organ system र organism हुन्। चार आधारभूत tissue प्रकार epithelial, connective, muscle र nervous tissue हुन्। Homeostasis भनेको negative feedback जस्ता नियमन प्रक्रियाबाट शरीरको आन्तरिक वातावरण तुलनात्मक रूपमा स्थिर राख्नु हो।"}'::jsonb,true),
('dph-anatomy-note-102','Pharmacy','Diploma in Pharmacy','note','free',502,'{"title":"Blood and Cardiovascular System","english":"Blood consists of plasma and formed elements: red blood cells, white blood cells and platelets. Red blood cells contain haemoglobin and transport oxygen; white blood cells participate in defence; platelets help haemostasis. The heart has four chambers and pumps blood through pulmonary and systemic circulation. Arteries carry blood away from the heart and veins carry blood toward it; oxygen content is not the defining feature of an artery or vein.","nepali":"रगतमा plasma र formed elements अर्थात् red blood cells, white blood cells र platelets हुन्छन्। Red blood cells मा haemoglobin हुन्छ र oxygen बोक्छन्; white blood cells ले शरीरको रक्षा गर्छन्; platelets ले haemostasis मा मद्दत गर्छन्। मुटुमा चार chamber हुन्छन् र pulmonary तथा systemic circulation मा रगत पम्प गर्छ। Artery ले मुटुबाट रगत बाहिर लैजान्छ र vein ले मुटुतर्फ ल्याउँछ; oxygen को मात्रा artery वा vein छुट्याउने परिभाषा होइन।"}'::json,true),
('dph-anatomy-note-103','Pharmacy','Diploma in Pharmacy','note','free',503,'{"title":"Respiratory and Digestive Systems","english":"The respiratory system conducts air through the nose, pharynx, larynx, trachea and bronchi to the lungs. Gas exchange occurs mainly across the alveolar-capillary membrane: oxygen enters blood and carbon dioxide leaves it. The digestive tract includes mouth, oesophagus, stomach, small intestine and large intestine. Most nutrient absorption occurs in the small intestine; the large intestine absorbs water and electrolytes and forms faeces.","nepali":"Respiratory system ले नाक, pharynx, larynx, trachea र bronchi हुँदै फोक्सोसम्म हावा पुर्‍याउँछ। मुख्य gas exchange alveolar-capillary membrane मा हुन्छ: oxygen रगतमा प्रवेश गर्छ र carbon dioxide बाहिर निस्कन्छ। Digestive tract मा mouth, oesophagus, stomach, small intestine र large intestine पर्छन्। धेरैजसो nutrient absorption small intestine मा हुन्छ; large intestine ले पानी र electrolyte सोस्छ र दिसा बनाउँछ।"}'::jsonb,true),
('dph-anatomy-note-104','Pharmacy','Diploma in Pharmacy','note','free',504,'{"title":"Nervous and Endocrine Systems","english":"The nervous system includes the central nervous system (brain and spinal cord) and peripheral nerves. Neurons transmit signals; synapses allow communication between neurons or target cells. The endocrine system consists of hormone-secreting glands. Hormones travel through blood and regulate functions such as growth, metabolism, reproduction and fluid balance. The hypothalamus links nervous and endocrine regulation, while the pituitary influences several other endocrine glands.","nepali":"Nervous system मा central nervous system (brain र spinal cord) तथा peripheral nerves पर्छन्। Neuron ले signal पठाउँछ र synapse ले neuron वा target cell बीच सञ्चार गराउँछ। Endocrine system hormone निकाल्ने gland हरूबाट बनेको हुन्छ। Hormone रगतमार्फत यात्रा गरी growth, metabolism, reproduction र fluid balance नियमन गर्छ। Hypothalamus ले nervous र endocrine regulation जोड्छ भने pituitary ले अन्य endocrine gland हरूलाई प्रभाव पार्छ।"}'::jsonb,true),
('dph-anatomy-note-105','Pharmacy','Diploma in Pharmacy','note','free',505,'{"title":"Urinary, Reproductive and Musculoskeletal Systems","english":"The kidneys filter blood and form urine; the nephron is the functional unit of the kidney. Urine passes through ureters to the urinary bladder and leaves through the urethra. The reproductive systems produce gametes and sex hormones. The musculoskeletal system includes bones, joints and skeletal muscles; it supports the body, protects organs and enables movement. Bone marrow is an important site of blood cell formation.","nepali":"Kidney ले रगत filter गरी urine बनाउँछ; nephron kidney को functional unit हो। Urine ureter हुँदै urinary bladder मा पुग्छ र urethra बाट बाहिर निस्कन्छ। Reproductive system ले gamete र sex hormone उत्पादन गर्छ। Musculoskeletal system मा bone, joint र skeletal muscle पर्छन्; यसले शरीरलाई support, अंगलाई protection र movement दिन्छ। Bone marrow रगतका कोषिका बन्ने महत्त्वपूर्ण स्थान हो।"}'::jsonb,true),
('dph-anatomy-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',501,'{"question":"The study of the functions of the human body is called:","translation":"मानव शरीरका कार्यहरूको अध्ययनलाई के भनिन्छ?","options":["Anatomy","Physiology","Histology","Pathology"],"correctIndex":1,"explanation":"Physiology studies how body parts and systems function.","explanationNe":"Physiology ले शरीरका अंग तथा system ले कसरी काम गर्छन् भन्ने अध्ययन गर्छ।"}'::jsonb,true),
('dph-anatomy-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',502,'{"question":"Which of the following is a basic type of tissue?","translation":"तलका मध्ये कुन आधारभूत tissue प्रकार हो?","options":["Epithelial","Enamel","Bile","Plasma"],"correctIndex":0,"explanation":"The four basic tissue types are epithelial, connective, muscle and nervous.","explanationNe":"चार आधारभूत tissue प्रकार epithelial, connective, muscle र nervous हुन्।"}'::jsonb,true),
('dph-anatomy-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',503,'{"question":"Which blood component primarily transports oxygen?","translation":"रगतको कुन भागले मुख्य रूपमा oxygen बोक्छ?","options":["Platelets","Red blood cells","Plasma proteins only","White blood cells"],"correctIndex":1,"explanation":"Haemoglobin in red blood cells binds and transports most oxygen in blood.","explanationNe":"Red blood cells मा भएको haemoglobin ले रगतमा धेरैजसो oxygen बाँधेर बोक्छ।"}'::jsonb,true),
('dph-anatomy-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',504,'{"question":"How many chambers are present in the human heart?","translation":"मानव मुटुमा कति वटा chamber हुन्छन्?","options":["Two","Three","Four","Five"],"correctIndex":2,"explanation":"The human heart has two atria and two ventricles.","explanationNe":"मानव मुटुमा दुई atria र दुई ventricles गरी चार chamber हुन्छन्।"}'::jsonb,true),
('dph-anatomy-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',505,'{"question":"The main site of gas exchange in the lungs is the:","translation":"फोक्सोमा gas exchange हुने मुख्य स्थान कुन हो?","options":["Trachea","Alveoli","Larynx","Pleura"],"correctIndex":1,"explanation":"Gas exchange occurs across the thin alveolar-capillary membrane.","explanationNe":"पातलो alveolar-capillary membrane हुँदै gas exchange हुन्छ।"}'::jsonb,true),
('dph-anatomy-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',506,'{"question":"Most nutrient absorption takes place in the:","translation":"धेरैजसो पोषक तत्त्व कहाँ सोसिन्छ?","options":["Stomach","Small intestine","Large intestine","Oesophagus"],"correctIndex":1,"explanation":"The small intestine is the principal site for absorption of digested nutrients.","explanationNe":"पचेका पोषक तत्त्व सोसिने मुख्य स्थान small intestine हो।"}'::jsonb,true),
('dph-anatomy-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',507,'{"question":"The structural and functional unit of the kidney is the:","translation":"Kidney को संरचनात्मक तथा कार्यात्मक एकाइ कुन हो?","options":["Neuron","Nephron","Alveolus","Osteon"],"correctIndex":1,"explanation":"Each nephron filters blood and contributes to urine formation.","explanationNe":"प्रत्येक nephron ले रगत filter गरी urine बन्ने प्रक्रियामा योगदान गर्छ।"}'::jsonb,true),
('dph-anatomy-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',508,'{"question":"Which organs form the central nervous system?","translation":"Central nervous system कुन अंगबाट बनेको हुन्छ?","options":["Brain and spinal cord","Heart and lungs","Kidneys and bladder","Muscles and bones"],"correctIndex":0,"explanation":"The central nervous system consists of the brain and spinal cord.","explanationNe":"Central nervous system मा brain र spinal cord पर्छन्।"}'::jsonb,true),
('dph-anatomy-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',509,'{"question":"Which gland is commonly called the master endocrine gland?","translation":"कुन gland लाई सामान्यतया master endocrine gland भनिन्छ?","options":["Thyroid","Pituitary","Adrenal","Pineal"],"correctIndex":1,"explanation":"The pituitary releases hormones that regulate several other endocrine glands, under hypothalamic control.","explanationNe":"Hypothalamus को नियन्त्रणमा pituitary ले अन्य endocrine gland हरूलाई नियमन गर्ने hormone निकाल्छ।"}'::jsonb,true),
('dph-anatomy-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',510,'{"question":"Which blood component is most directly involved in clot formation?","translation":"रगत जम्ने प्रक्रियामा कुन भाग प्रत्यक्ष संलग्न हुन्छ?","options":["Platelets","Red blood cells","Albumin","Neurons"],"correctIndex":0,"explanation":"Platelets adhere and aggregate at sites of vessel injury and support haemostasis.","explanationNe":"रक्तनलीमा चोट लाग्दा platelets टाँसिएर जम्मा हुन्छन् र haemostasis मा सहयोग गर्छन्।"}'::jsonb,true),
('dph-anatomy-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',601,'{"question":"Differentiate anatomy and physiology. Name the four basic tissue types.","answer":"Anatomy studies body structures; physiology studies their functions. The four basic tissue types are epithelial, connective, muscle and nervous tissue.","answerNe":"Anatomy ले शरीरका संरचना र physiology ले तिनका कार्य अध्ययन गर्छ। चार tissue प्रकार epithelial, connective, muscle र nervous हुन्।"}'::jsonb,true),
('dph-anatomy-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',602,'{"question":"Describe the components of blood and state one function of each formed element.","answer":"Blood contains plasma and formed elements. Red cells transport oxygen, white cells provide immune defence and platelets support haemostasis.","answerNe":"रगतमा plasma र formed elements हुन्छन्। Red cells ले oxygen बोक्छन्, white cells ले प्रतिरक्षा गर्छन् र platelets ले रगत जमाउन मद्दत गर्छन्।"}'::jsonb,true),
('dph-anatomy-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',603,'{"question":"Trace the path of air to the gas-exchange region and state where gas exchange occurs.","answer":"Air passes through the nose, pharynx, larynx, trachea and bronchi to the lungs; gas exchange occurs mainly across the alveolar-capillary membrane.","answerNe":"हावा nose, pharynx, larynx, trachea र bronchi हुँदै फोक्सो पुग्छ; gas exchange मुख्यतः alveolar-capillary membrane मा हुन्छ।"}'::jsonb,true),
('dph-anatomy-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',604,'{"question":"Name the functional unit of the kidney and outline the route of urine out of the body.","answer":"The nephron is the functional unit. Urine passes from collecting ducts into renal pelvis, ureter, urinary bladder and urethra.","answerNe":"Nephron kidney को functional unit हो। Urine collecting duct बाट renal pelvis, ureter, urinary bladder र urethra हुँदै बाहिर निस्कन्छ।"}'::jsonb,true),
('dph-anatomy-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',605,'{"question":"Explain homeostasis and give one example of negative feedback.","answer":"Homeostasis maintains a relatively stable internal environment. For example, increased blood glucose stimulates insulin release, which helps lower blood glucose toward its normal range.","answerNe":"Homeostasis ले शरीरको आन्तरिक वातावरण तुलनात्मक रूपमा स्थिर राख्छ। उदाहरणका लागि blood glucose बढ्दा insulin निस्कन्छ र glucose लाई सामान्य दायरातर्फ घटाउन मद्दत गर्छ।"}'::jsonb,true)
